{"path":"/root/inspect_more.py","content":"from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
for sheet in ['Task','Data']:
    ws=wb[sheet]
    print('\n===', sheet, 'merged ranges ===')
    print(list(ws.merged_cells.ranges))
    print('\nNon-empty cells A1:L50:')
    for r in range(1, min(ws.max_row,50)+1):
        vals=[]
        for c in range(1, min(ws.max_column,12)+1):
            v=ws.cell(r,c).value
            if v is not None:
                vals.append(f'{get_column_letter(c)}={v!r}')
        if vals:
            print(f'{r}: '+', '.join(vals))
